package com.nextaicommerce.platform.marketplace;
import java.util.*;import java.time.*;import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class ShopifySkuCsvExportTest {
 final UUID tenant=new UUID(0,1),connection=new UUID(0,2);final ShopifySkuRepository repo=mock(ShopifySkuRepository.class);final ShopifySkuCsvExport csv=new ShopifySkuCsvExport(repo);
 static ShopifySkuRepository.Row row(UUID id,String sku){return new ShopifySkuRepository.Row(id,"gid://shopify/ProductVariant/2","gid://shopify/Product/1","gid://shopify/InventoryItem/3",sku,"Pizza","Default Title","[]","[]","ACTIVE",new BigDecimal("19.99"),"USD",null,null,"unit.myshopify.com","hash",Instant.EPOCH,false,false);}
 @Test void exportsChosenVisibleGroupsOnlyAndProtectsFormulaText(){var r=row(new UUID(0,3),"=cmd");when(repo.list(eq(tenant),eq(connection),anyString(),anyString(),anyString(),anyString(),eq(0),eq(100))).thenReturn(new ShopifySkuRepository.Page(List.of(r),1,0,100));when(repo.componentBatch(any(),any(),anyList())).thenReturn(Map.of());var a=csv.generate(tenant,connection,Map.of("columns","product-details,price-shipping,available"));String text=new String(a.bytes(),StandardCharsets.UTF_8);assertThat(text).startsWith("\ufeff").contains("\"'=cmd\"","\"19.99\"","\"USD\"").doesNotContain("Barcode","inventory item ID","data state","Mapped item 20","Shopify product ID","Shopify variant ID","gid://shopify/");assertThat(a.rows()).isEqualTo(1);}
 @Test void visibleMappedCodeQuantityRemainAtomicAndOrdered(){var p=new MarketplaceSkuRepository.MappingComponentView(new UUID(0,4),"Pizza","000033",null,new BigDecimal("12"));var out=ShopifySkuCsvExport.project(row(new UUID(0,3),"00001"),List.of(p),List.of("price-shipping","product-details"));assertThat(new ArrayList<>(out.keySet()).subList(0,2)).containsExactly("Listing price","Currency");assertThat(out.get("Seller SKU")).isEqualTo("00001");assertThat(out.get("Mapped item 1 code")).isEqualTo("000033");assertThat(out.get("Mapped item 1 quantity per listing unit")).isEqualTo(new BigDecimal("12"));assertThat(out.keySet()).noneMatch(x->x.contains("state")||x.contains("Barcode")||x.contains("Shopify"));}
 @Test void suppressesOnlyTheMeaninglessDefaultOption(){var v=row(new UUID(0,3),"sku");var options=new ShopifySkuRepository.Row(v.id(),v.gid(),v.productGid(),v.inventoryGid(),v.sku(),v.title(),v.variantTitle(),"[{\"name\":\"Title\",\"value\":\"Default Title\"},{\"name\":\"Flavor\",\"value\":\"Chocolate\"}]",v.barcodes(),v.productStatus(),v.price(),v.currency(),v.image(),v.storefront(),v.shop(),v.revision(),v.observed(),v.mapped(),v.blocked());assertThat(options.optionsLabel()).isEqualTo("Flavor: Chocolate");}
 @Test void incompleteOrRepeatedTraversalFailsBeforeArtifact(){var r=row(new UUID(0,3),"a");when(repo.list(eq(tenant),eq(connection),anyString(),anyString(),anyString(),anyString(),anyInt(),eq(100))).thenReturn(new ShopifySkuRepository.Page(List.of(r),101,0,100));when(repo.componentBatch(any(),any(),anyList())).thenReturn(Map.of());assertThatThrownBy(()->csv.generate(tenant,connection,Map.of())).isInstanceOf(IllegalArgumentException.class).hasMessageContaining("Repeated");}
 @Test void invalidHiddenColumnsAndMalformedFilterTypesFailClosed(){assertThatThrownBy(()->csv.generate(tenant,connection,Map.of("columns","product-details,actions"))).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->csv.generate(tenant,connection,Map.of("columnFilters","{\"price-shipping\":{\"min\":\"1\"}}"))).isInstanceOf(IllegalArgumentException.class);verifyNoInteractions(repo);}
}
